B.Xt=s(["\uc5b4\uc11c \uc624\uc138\uc694. \uae30\ub2e4\ub9ac\uace0 \uc788\uc5c8\ub2f5\ub2c8\ub2e4.","\ud638\uc624, \uc81c\ubc95 \ubcf4\ub294 \ub208\uc774 \uc788\uc73c\uc2dc\uad70\uc694.","\uc88b\uc740 \ubb3c\uac74\uc740 \uc8fc\uc778\uc744 \uc54c\uc544\ubcf4\ub294 \ubc95\uc774\uc8e0.","\ud6c4\ud6c4, \uac00\uaca9\ubcf4\ub2e4 \uc0ac\uc5f0\uc774 \ube44\uc2fc \ubb3c\uac74\uc774\ub78d\ub2c8\ub2e4.","\uc774 \ubb3c\uac74\uc758 \uc804 \uc8fc\uc778\uc774\uc694? \uae00\uc384\uc694.","\uc138\uc0c1\uc5d0 \uc6b0\uc5f0\ud55c \uac70\ub798\ub780 \uc5c6\ub2f5\ub2c8\ub2e4.","\uae4c\ub9c8\uadc0\uac00 \uc6b8\uba74 \uc190\ub2d8\uc774 \uc628\ub2e4\ub354\uad70\uc694.","\ube44\ubc00\uc740 \ub54c\ub85c \uae08\ud654\ubcf4\ub2e4 \uac12\uc9c0\ub2f5\ub2c8\ub2e4.","\ud6c4\ud6c4, \uadf8 \ubb3c\uac74\uc774 \ub9c8\uc74c\uc5d0 \ub4dc\uc2dc\ub098\uc694?","\uc624\ub798\ub41c \ubb3c\uac74\uc77c\uc218\ub85d \uc774\uc57c\uae30\uac00 \uae4a\uc5b4\uc9c0\uc8e0.","\uac71\uc815 \ub9c8\uc138\uc694. \uc800\uc8fc\ub294 \ubcc4\ub3c4 \uc694\uae08\uc774\ub2c8\uae4c\uc694.","\uc81c \ub208\uc744 \ubbff\uc73c\uc154\ub3c4 \uc88b\uc2b5\ub2c8\ub2e4. \uc544\ub9c8\ub3c4\uc694.","\uac00\ubb38\uc758 \uc720\uc0b0\uc740 \ud568\ubd80\ub85c \n\uac12\uc744 \ub9e4\uae38 \uc218 \uc5c6\uc8e0.","\uc5b4\ub5a4 \ubb3c\uac74\uc740 \uc8fc\uc778\uc744 \n\uae30\ub2e4\ub9b0\ub2f5\ub2c8\ub2e4.","\ud750\uc74c, \uc624\ub298\uc740 \uc6b4\uc774 \uc88b\uc73c\uc2e0 \ubaa8\uc591\uc774\ub124\uc694.","\uae4c\ub9c8\uadc0\ub294 \ubc18\uc9dd\uc774\ub294 \uac83\ub9cc \ud0d0\ub0b4\uc9c0 \uc54a\uc544\uc694.","\ud6c4\ud6c4, \uadf8\uac74 \uc81c\ubc95 \uc704\ud5d8\ud55c \uc120\ud0dd\uc778\ub370\uc694?","\ubb3c\uac74\uc758 \uac00\uce58\ub294 \uc4f0\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub2ec\ub838\uc8e0.","\uc783\uc5b4\ubc84\ub9b0 \uac83\uc740 \uc5b8\uc820\uac00 \ub3cc\uc544\uc624\ub294 \ubc95\uc774\uc8e0.","\uac12\uc744 \uae4e\uc544\ub2ec\ub77c\uace0\uc694? \uace4\ub780\ud55c\ub370\uc694, \ud6c4\ud6c4.","\uc81c \uac00\ubc29\uc5d4 \uc5c6\ub294 \uac8c \uc5c6\ub2f5\ub2c8\ub2e4. \uac70\uc758\uc694.","\uc624\ub798\ub41c \uc57d\uc18d\ub3c4 \uac70\ub798\uac00 \ub420 \uc218 \uc788\ub2f5\ub2c8\ub2e4.","\uadf8 \ubb38\uc591\uc774 \ub0af\uc775\uc73c\uc2e0\uac00\uc694? \n\ud765\ubbf8\ub86d\uad70\uc694.","\uae4c\ub9c8\uadc0\ub294 \uc8fd\uc740 \uc790\uc758 \ube44\ubc00\ub3c4 \uae30\uc5b5\ud558\uc8e0.","\ud6c4\ud6c4, \ub108\ubb34 \uae4a\uc774 \ub4e4\uc5ec\ub2e4\ubcf4\uc9c4 \ub9c8\uc138\uc694.","\uc88b\uc740 \uac70\ub798\uc5d0\ub294 \uc57d\uac04\uc758 \ube44\ubc00\uc774 \ud544\uc694\ud558\uc8e0.","\uc774 \ubb3c\uac74\uc774 \uc5b4\ub514\uc11c \ub0ac\ub0d0\uace0\uc694? \n\ube44\ubc00\uc785\ub2c8\ub2e4.","\uc5b8\uc820\uac00 \uc774 \uac70\ub798\ub97c \ub5a0\uc62c\ub9ac\uc2e4 \uac81\ub2c8\ub2e4.","\uc190\ud574 \ubcf4\ub294 \uc7a5\uc0ac\ub294 \ud558\uc9c0 \uc54a\ub294 \uc8fc\uc758\ub77c\uc11c\uc694.","\ud6c4\ud6c4, \ub2e4\uc74c \uac70\ub798\ub3c4 \uae30\ub300\ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.Yh=s(["\uc88b\uc740 \uc544\uce68\uc785\ub2c8\ub2e4. \n\uae4c\ub9c8\uadc0\ub3c4 \uae68\uc5b4\ub0ac\uad70\uc694.","\uc774\ub978 \uc190\ub2d8\uc774\ub77c\ub2c8, \n\uae30\ubd84 \uc88b\uc740 \uc2dc\uc791\uc774\ub124\uc694.","\uc544\uce68 \ud587\uc0b4\uc5d4 \ubcf4\uc11d\uc774 \ub354 \ube5b\ub098 \ubcf4\uc774\uc8e0.","\ud6c4\ud6c4, \uc624\ub298\uc740 \uc5b4\ub5a4 \uc778\uc5f0\uc774 \uae30\ub2e4\ub9b4\uae4c\uc694?","\uc0c8\ubcbd\uc5d0 \uc7ac\ubbf8\uc788\ub294 \ubb3c\uac74\uc744 \uad6c\ud588\ub2f5\ub2c8\ub2e4."],t.s)
B.Zl=s(["\ud587\uc0b4\uc774 \uc88b\uad70\uc694. \uac70\ub798\ud558\uae30 \uc88b\uc740 \ub0a0\uc785\ub2c8\ub2e4.","\ucc28 \ud55c \uc794 \uc5b4\ub5a0\uc2e0\uac00\uc694? \uc774\uc57c\uae30\ub294 \ub364\uc774\uc8e0.","\ud6c4\ud6c4, \uc624\ub298 \uc7a5\uc0ac\ub294 \uc81c\ubc95 \uc21c\uc870\ub86d\ub124\uc694.","\uae4c\ub9c8\uadc0\ub3c4 \ub0ae\uc5d0\ub294 \uc870\uc6a9\ud55c \ubc95\uc774\uc8e0.","\uc88b\uc740 \ubb3c\uac74\uc740 \ubc1d\uc744 \ub54c \uc0b4\ud3b4\ubd10\uc57c\uc8e0."],t.s)
B.W1=s(["\ud574\uac00 \uc9c0\uba74 \uc624\ub798\ub41c \uc774\uc57c\uae30\uac00 \uae68\uc5b4\ub098\uc8e0.","\uc800\ub141\ub178\uc744\uc774 \uaf2d \uc624\ub798\ub41c \uae08\ud654 \uac19\uad70\uc694.","\ud6c4\ud6c4, \ubc24\uc758 \uac70\ub798\ub294 \uc870\uae08 \ud2b9\ubcc4\ud558\ub2f5\ub2c8\ub2e4.","\uae4c\ub9c8\uadc0\ub4e4\uc774 \ub3cc\uc544\uc624\ub294 \uc2dc\uac04\uc774\uad70\uc694.","\uc624\ub298\uc758 \ub9c8\uc9c0\ub9c9 \uac70\ub798\uac00 \ub420\uae4c\uc694?"],t.s)
B.Vn=s(["\uc774 \ub2a6\uc740 \uc2dc\uac04\uc5d0... \uadc0\ud55c \uc190\ub2d8\uc774\uc2dc\uad70\uc694.","\ud6c4\ud6c4, \ube44\ubc00 \uac70\ub798\ub294 \ubc24\uc5d0 \uc5b4\uc6b8\ub9ac\uc8e0.","\ub2ec\ube5b \uc544\ub798\uc120 \uc9c4\ud488\ub3c4 \ub2ec\ub77c \ubcf4\uc778\ub2f5\ub2c8\ub2e4.","\uae4c\ub9c8\uadc0\uac00 \uc6b8\uc5c8\uad70\uc694. \n\uc190\ub2d8\uc774 \uc62c \uc904 \uc54c\uc558\uc8e0.","\ubc24\uc5d0\ub294 \ubb3c\uac74\ubcf4\ub2e4 \uc774\uc57c\uae30\uac00 \uc798 \ud314\ub9ac\uc8e0.","\uc27f, \uc624\ub798\ub41c \uc720\uc0b0\uc774 \uc7a0\ub4e4\uc5b4 \uc788\ub2f5\ub2c8\ub2e4."],t.s)
